<?php require_once __DIR__.'/../includes/functions.php';require_admin();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();db()->prepare('UPDATE wilayas SET office_shipping_price=?,home_shipping_price=?,delivery_time=? WHERE id=?')->execute([$_POST['office_shipping_price'],$_POST['home_shipping_price'],$_POST['delivery_time'],$_POST['id']]);flash('success','تم تحديث سعري التوصيل.');header('Location: '.base('admin/shipping.php'));exit;}$adminTitle='الشحن والولايات';$rows=db()->query('SELECT * FROM wilayas ORDER BY code')->fetchAll();include 'header.php';?><div class="panel"><p class="muted">حددي سعراً مستقلاً للتوصيل إلى المكتب وإلى المنزل لكل ولاية.</p><table class="table"><tr><th>الرمز</th><th>الولاية</th><th>إلى المكتب</th><th>إلى المنزل</th><th>المدة</th><th></th></tr><?php foreach($rows as $r):?><tr><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$r['id']?>"><td><?=$r['code']?></td><td><?=e($r['name'])?></td><td><input name="office_shipping_price" value="<?=$r['office_shipping_price']?>"></td><td><input name="home_shipping_price" value="<?=$r['home_shipping_price']?>"></td><td><input name="delivery_time" value="<?=e($r['delivery_time'])?>"></td><td><button class="button">حفظ</button></td></form></tr><?php endforeach;?></table></div><?php include 'footer.php';?>
